      "path": "store.js",
      "content": "// ============================================================\n// DSH 花费统计插件 —— 存储层（纯 Node，可独立测试）\n//\n// 数据保留策略（v1.1.2 起）：\n//   明细记录（details）保留最近 DETAIL_DAYS 天；更早的记录自动按\n//   「天 + 模型」压缩为永久日汇总（rollups）。全时段统计 = 明细 + 汇总，\n//   永远精确，且内存 / 磁盘 / 写入量有界。\n//\n// 云端同步支持（v1.8.0 起）：\n//   · 每条明细带单调递增 `seq`（加载时补齐、写入时分配），云端凭它增量拉取；\n//   · `resetEpoch` 在 clear() 时 +1，使「清空后重新导入」不被云端判为重复；\n//   · seq 与 resetEpoch 随文件持久化，旧文件（无这两个字段）自动兼容升级。\n//\n// 文件格式：\n//   v2: { v: 2, seq: n, resetEpoch: n, details: [...], rollups: { dayKey: { modelKey: entry } } }\n//   v1（旧版裸数组）在 load() 时自动迁移；损坏文件自动备份为\n//   .corrupt-<时间戳> 并从零开始，不阻断启动。\n// ============================================================\nimport { existsSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from 'node:fs'\nimport { dirname } from 'node:path'\nimport { createHash } from 'node:crypto'\n\n/** 明细保留天数（更早的记录折叠进日汇总） */\nexport const DETAIL_DAYS = 180\n/** 图表按天轴最大跨度（天） */\nexport const MAX_AXIS_DAYS = 730\n/** 明细安全上限（纯兜底；180 天内几乎不可达） */\nexport const MAX_DETAILS = 200000\nconst DAY_MS = 86400000\n\nfunction pad2(n) { return n < 10 ? '0' + n : '' + n }\n\n/** 北京时间（UTC+8）的日期键 YYYY-MM-DD */\nexport function dayKey(ts) {\n  const d = new Date(ts + 28800000)\n  return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate())\n}\n\nexport function modelKeyOf(r) {\n  return r.provider + '/' + r.model\n}\n\nexport function emptyEntry(provider, model, subscription, estimated) {\n  return {\n    provider, model,\n    subscription: !!subscription,\n    estimated: !!estimated,\n    calls: 0, input: 0, output: 0, cacheRead: 0, cacheWrite: 0,\n    cost: 0, peak: 0, off: 0, flat: 0,\n  }\n}\n\n/** 单条日汇总最多记录多少条被吸收明细的键（云端据此排除重复，超出部分不再追溯） */\nexport const MAX_ABSORBED_KEYS = 5000\n\n// ---------- 原子落盘（Windows 友好） ----------\n/**\n * rename 的**瞬时**失败码。Windows 上目标文件被短暂占用时 renameSync 会抛这些：\n *   · 杀毒 / 搜索索引器刚扫过刚写完的临时文件；\n *   · 资源管理器预览、备份/同步工具正在读该文件；\n *   · 上一个 dsh 实例还没退干净（或同时跑了两个实例）。\n * 这类「等一下就好」，退避重试即可；代码类错误（ENOENT、EISDIR…）不该重试。\n */\nconst TRANSIENT_RENAME_CODES = new Set(['EPERM', 'EACCES', 'EBUSY'])\nexport function isTransientRenameError(e) {\n  return !!e && TRANSIENT_RENAME_CODES.has(String(e.code || ''))\n}\n\n/** 同步睡眠（Node 没有 sleepSync；Atomics.wait 不占 CPU） */\nfunction sleepSync(ms) {\n  try {\n    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms)\n  } catch (e) {\n    const end = Date.now() + ms\n    while (Date.now() < end) { /* 无 SharedArrayBuffer 的极端环境下退化为忙等 */ }\n  }\n}\n\n/**\n * 私有目录 / 文件的创建模式：POSIX 上 owner-only（0o700 / 0o600）。\n *\n * 为什么需要：`~/.dsh/storages` 里的记录含**完整用量明细**（会话、模型、token、\n * 花费，未脱敏时还有 sessionId），而默认 umask（常见 022）会让同机其他用户可读。\n * Windows 会忽略 mode，行为不变；POSIX 上显式收紧到 owner-only。\n * 已有文件不会被 chmod 改写（只影响新建），避免动到用户既有部署的权限策略。\n */\nexport const PRIVATE_DIR_MODE = 0o700\nexport const PRIVATE_FILE_MODE = 0o600\n\n/**\n * 原子落盘：写临时文件 → rename 覆盖目标。\n *\n * · 临时文件名带 **pid**：两个实例各写各的临时文件，不会互相盖掉半个文件\n *   （旧实现固定用 `<file>.tmp`，两实例必然抢同一个临时文件）。\n * · rename 遇瞬时占用时按 20/40/80/160ms 退避重试（默认 5 次，约 0.3s）。\n * · 仍失败**不做**「直接覆盖写」：那会让并发读方看到半个 JSON，而 store.load()\n *   一旦读到半个 JSON 会把文件改名为 `.corrupt-*` 并清空 —— 损失远大于「晚几秒落盘」。\n *   数据留在内存里，由调用方稍后重试（见 index.js 的 writeRecords 重试链）。\n *\n * @returns {{ok:boolean, attempts:number, mode:'rename'|'failed', error?:Error|null, transient?:boolean}}\n */\nexport function writeFileAtomic(filePath, data, opts) {\n  const o = opts || {}\n  const fs = Object.assign({ mkdirSync, writeFileSync, renameSync, unlinkSync }, o.fs || {})\n  const sleep = o.sleep || sleepSync\n  const tries = Math.max(1, Number(o.tries) || 5)\n  const tmp = filePath + '.' + process.pid + '.tmp'\n  const cleanup = () => { try { fs.unlinkSync(tmp) } catch (e) { /* 已被 rename 走或从未创建 */ } }\n  try {\n    fs.mkdirSync(dirname(filePath), { recursive: true, mode: PRIVATE_DIR_MODE })\n    fs.writeFileSync(tmp, data, { encoding: 'utf8', mode: PRIVATE_FILE_MODE })\n  } catch (e) {\n    cleanup()\n    return { ok: false, attempts: 0, mode: 'failed', error: e, transient: isTransientRenameError(e) }\n  }\n  let attempts = 0\n  let last = null\n  for (let i = 0; i < tries; i++) {\n    attempts += 1\n    try {\n      fs.renameSync(tmp, filePath)\n      return { ok: true, attempts, mode: 'rename', error: last }\n    } catch (e) {\n      last = e\n      if (!isTransientRenameError(e)) break\n      if (i < tries - 1) sleep(20 * Math.pow(2, i))\n    }\n  }\n  cleanup()\n  return { ok: false, attempts, mode: 'failed', error: last, transient: isTransientRenameError(last) }\n}\n\n/** 给用户看的失败原因（区分「被占用」与「文件系统错误」） */\nfunction explainPersistError(res) {\n  if (res.transient) {\n    return '记录文件被占用（杀毒/索引器/备份工具正在读它，或另有一个 dsh 实例在跑；'\n      + 'Windows 上 rename 需要目标文件的删除权限，被占用时会失败）'\n  }\n  return '文件系统错误（不是占用问题）'\n}\n\n// ---------- 实例锁（只提示，不阻断） ----------\n/** 进程是否存活：Windows 上 EPERM 表示「存在但无权限」，同样算存活 */\nfunction pidAlive(pid) {\n  try {\n    process.kill(pid, 0)\n    return true\n  } catch (e) {\n    return !!e && e.code === 'EPERM'\n  }\n}\n\n/**\n * 检测同一份记录文件是否已被**另一个存活的 dsh 实例**占用。\n *\n * 为什么需要：两个实例同时写同一份记录会互相覆盖，并且在 Windows 上很容易撞上\n * rename 的 EPERM（v1.8.10 的现场根因就是「上一个实例还在跑，又起了一个」）。\n * 与其让用户对着 EPERM 堆栈猜，不如启动时直接说清楚。\n * 纯提示：读不到 / 解析失败 / 陈旧锁都返回 null，绝不阻断启动。\n * @returns {{heldBy:number|null, text:string|null}}\n */\nexport function checkStoreLock(filePath, opts) {\n  const o = opts || {}\n  const isAlive = o.isAlive || pidAlive\n  const lockFile = filePath + '.lock'\n  try {\n    if (!existsSync(lockFile)) return { heldBy: null, text: null }\n    const prev = JSON.parse(readFileSync(lockFile, 'utf8'))\n    const pid = Number(prev && prev.pid)\n    if (!pid || pid === process.pid || !isAlive(pid)) return { heldBy: null, text: null }\n    return {\n      heldBy: pid,\n      text: 'cost tracker: 检测到另一个 dsh 实例（PID ' + pid + (prev && prev.version ? ' · v' + prev.version : '')\n        + '）正在使用同一份记录文件：\\n  ' + filePath\n        + '\\n  两个实例会互相覆盖对方的记录，并可能在 Windows 上触发 rename EPERM（需要目标文件的删除权限）。'\n        + '\\n  请只保留一个 dsh 实例：先 Ctrl+C 停掉旧的，再启动新的。',\n    }\n  } catch (e) {\n    return { heldBy: null, text: null }\n  }\n}\n\n/** 写下本进程的实例锁（带上版本，便于提示里说清是谁占着） */\nexport function writeStoreLock(filePath, opts) {\n  const o = opts || {}\n  try {\n    mkdirSync(dirname(filePath), { recursive: true, mode: PRIVATE_DIR_MODE })\n    writeFileSync(filePath + '.lock', JSON.stringify({ pid: process.pid, at: Date.now(), version: o.version || '' }), { encoding: 'utf8', mode: PRIVATE_FILE_MODE })\n    return true\n  } catch (e) {\n    return false\n  }\n}\n\n/** 退出时清理实例锁（只删自己的，别删别人的） */\nexport function releaseStoreLock(filePath) {\n  const lockFile = filePath + '.lock'\n  try {\n    const prev = JSON.parse(readFileSync(lockFile, 'utf8'))\n    if (Number(prev && prev.pid) === process.pid) unlinkSync(lockFile)\n    return true\n  } catch (e) {\n    return false\n  }\n}\n\n\n\n/**\n * 由插件侧统一计算明细的内容哈希键（与云端契约 §6 一致）。\n * 这里即时计算而不是在 store 里 import sync.js —— 该函数只依赖 node:crypto，\n * 复用它可保证「本地折叠」与「云端去重」用的是同一个键。\n * @param {object} r - 明细记录\n * @param {number} resetEpoch - 清空纪元\n */\nexport function recordHashKey(r, resetEpoch) {\n  const US = '\\u001f'\n  const s = (v) => (v === undefined || v === null ? '' : String(v).trim())\n  const i = (v) => { const n = Number(v); return Number.isFinite(n) ? Math.trunc(n) : 0 }\n  const c6 = (v) => { const n = Number(v); return !Number.isFinite(n) || n === 0 ? '0' : String(Math.round(n * 1e6) / 1e6) }\n  const t = (r && r.tokens) || {}\n  const canonical = [\n    'detail', i(resetEpoch), i(r && r.ts),\n    s(r && r.provider).toLowerCase(), s(r && r.model).toLowerCase(),\n    s(r && r.sessionId), s(r && r.purpose),\n    i(t.input), i(t.output), i(t.cacheRead), i(t.cacheWrite), i(t.reasoning),\n    c6(r && r.cost),\n  ].join(US)\n  return createHash('sha256').update(canonical, 'utf8').digest('hex')\n}\n\nexport function mergeIntoEntry(entry, r) {\n  entry.calls += 1\n  entry.input += r.tokens.input\n  entry.output += r.tokens.output\n  entry.cacheRead += r.tokens.cacheRead\n  entry.cacheWrite += r.tokens.cacheWrite\n  entry.cost += r.cost\n  if (r.period === 'peak') entry.peak += r.cost\n  else if (r.period === 'off-peak') entry.off += r.cost\n  else entry.flat += r.cost\n  return entry\n}\n\n/**\n * 把一条记录折叠进 rollups（按 dayKey + modelKey）。\n * 同时记录被吸收明细的内容哈希（`absorbed`），供云端排除重复统计 ——\n * 这是「明细超期后仍能全时段精确」的关键：快照 + 被吸收键声明。\n * @param {object} rollups - 日汇总容器\n * @param {object} r - 明细记录\n * @param {number} [resetEpoch] - 清空纪元（参与哈希）\n */\nexport function rollupRecord(rollups, r, resetEpoch) {\n  const dk = dayKey(r.ts)\n  const mk = modelKeyOf(r)\n  const day = rollups[dk] || (rollups[dk] = {})\n  const entry = day[mk] || (day[mk] = emptyEntry(r.provider, r.model, r.subscription, r.estimated))\n  mergeIntoEntry(entry, r)\n  if (!Array.isArray(entry.absorbed)) entry.absorbed = []\n  if (entry.absorbed.length < MAX_ABSORBED_KEYS) entry.absorbed.push(recordHashKey(r, resetEpoch || 0))\n  if (entry.absorbed.length === MAX_ABSORBED_KEYS) entry.absorbedTruncated = true\n  return entry\n}\n\n/** 把 details 中早于保留窗口的记录折叠进 rollups，返回折叠条数（details 为按时间升序） */\nexport function applyRetention(details, rollups, now, detailDays = DETAIL_DAYS, resetEpoch = 0) {\n  const cutoff = now - detailDays * DAY_MS\n  let i = 0\n  while (i < details.length && details[i].ts < cutoff) {\n    rollupRecord(rollups, details[i], resetEpoch)\n    i++\n  }\n  if (i > 0) details.splice(0, i)\n  return i\n}\n\n/**\n * 全时段汇总（明细 + 日汇总）。口径与 buildSummary 一致：\n * 按量计费与订阅（等效费用）分开统计。\n * @returns {{realCost:number, realCalls:number, realTokens:number,\n *            subEquivalent:number, subCalls:number, subTokens:number,\n *            byModel:Map<string,{model:string, subscription:boolean, estimated:boolean,\n *                                 calls:number, tokens:number, cost:number}>}}\n */\nexport function collectTotals(details, rollups) {\n  const t = { realCost: 0, realCalls: 0, realTokens: 0, subEquivalent: 0, subCalls: 0, subTokens: 0, byModel: new Map() }\n  const add = (provider, model, subscription, estimated, calls, tokens, cost) => {\n    const key = modelKeyOf({ provider, model })\n    let m = t.byModel.get(key)\n    if (!m) {\n      m = { model: key, subscription: !!subscription, estimated: !!estimated, calls: 0, tokens: 0, cost: 0 }\n      t.byModel.set(key, m)\n    }\n    m.calls += calls\n    m.tokens += tokens\n    m.cost += cost\n    if (subscription) { t.subCalls += calls; t.subEquivalent += cost; t.subTokens += tokens }\n    else { t.realCalls += calls; t.realCost += cost; t.realTokens += tokens }\n  }\n  for (const r of details) {\n    add(r.provider, r.model, r.subscription, r.estimated, 1, r.tokens.input + r.tokens.output + r.tokens.cacheRead + r.tokens.cacheWrite, r.cost)\n  }\n  for (const dk of Object.keys(rollups)) {\n    const day = rollups[dk]\n    for (const mk of Object.keys(day)) {\n      const e = day[mk]\n      add(e.provider, e.model, e.subscription, e.estimated, e.calls, e.input + e.output + e.cacheRead + e.cacheWrite, e.cost)\n    }\n  }\n  return t\n}\n\n/**\n * 按天聚合（明细 + 日汇总）：dayKey -> 当日分段\n * @returns {Map<string,{peak:number, off:number, flat:number, cost:number, calls:number, tokens:number, subCost:number, subCalls:number}>}\n */\nexport function collectByDay(details, rollups) {\n  const days = new Map()\n  const ensure = (dk) => {\n    let d = days.get(dk)\n    if (!d) {\n      d = { peak: 0, off: 0, flat: 0, cost: 0, calls: 0, tokens: 0, subCost: 0, subCalls: 0 }\n      days.set(dk, d)\n    }\n    return d\n  }\n  for (const r of details) {\n    const d = ensure(dayKey(r.ts))\n    const total = r.tokens.input + r.tokens.output + r.tokens.cacheRead + r.tokens.cacheWrite\n    d.tokens += total\n    if (r.subscription) { d.subCost += r.cost; d.subCalls += 1 }\n    else {\n      d.calls += 1\n      d.cost += r.cost\n      if (r.period === 'peak') d.peak += r.cost\n      else if (r.period === 'off-peak') d.off += r.cost\n      else d.flat += r.cost\n    }\n  }\n  for (const dk of Object.keys(rollups)) {\n    const d = ensure(dk)\n    for (const mk of Object.keys(rollups[dk])) {\n      const e = rollups[dk][mk]\n      const total = e.input + e.output + e.cacheRead + e.cacheWrite\n      d.tokens += total\n      if (e.subscription) { d.subCost += e.cost; d.subCalls += e.calls }\n      else {\n        d.calls += e.calls\n        d.cost += e.cost\n        d.peak += e.peak\n        d.off += e.off\n        d.flat += e.flat\n      }\n    }\n  }\n  return days\n}\n\n/**\n * 创建存储。details/rollups 为原地可变引用。\n * @param {string} filePath - 数据文件路径\n * @param {{detailDays?:number, maxDetails?:number}} [opts] - 测试可覆盖默认值\n */\nexport function createStore(filePath, opts) {\n  const detailDays = (opts && opts.detailDays) || DETAIL_DAYS\n  const maxDetails = (opts && opts.maxDetails) || MAX_DETAILS\n  const details = []\n  const rollups = {}\n  /** 单调递增的明细序号（云端增量同步用） */\n  let seq = 0\n  /** 清空计数：clear() 时 +1，使重新导入的数据不被云端判为重复 */\n  let resetEpoch = 0\n  /** 本次加载是否为旧文件（缺 seq 字段）——需要补配序号并落盘 */\n  let needsNumbering = false\n\n  /** 按时间升序补配 seq（旧文件升级路径） */\n  function assignSeq() {\n    const sorted = details.slice().sort((a, b) => (a.ts || 0) - (b.ts || 0))\n    let n = seq\n    for (const r of sorted) n += 1\n    // 按排序结果分配：最老者序号最小，与上报顺序一致\n    let i = n - details.length + 1\n    for (const r of sorted) { r.seq = i; i += 1 }\n    // details 需保持按时间升序（写入顺序）：排序后回填\n    sorted.sort((a, b) => (a.seq || 0) - (b.seq || 0))\n    details.length = 0\n    for (const r of sorted) details.push(r)\n    seq = n\n  }\n\n  function load() {\n    try {\n      if (!existsSync(filePath)) return\n      const parsed = JSON.parse(readFileSync(filePath, 'utf8'))\n      if (Array.isArray(parsed)) {\n        // v1：旧版裸数组，逐条迁移\n        for (const r of parsed) if (isRecord(r)) details.push(r)\n      } else if (parsed && typeof parsed === 'object') {\n        if (Number.isFinite(parsed.seq)) seq = Math.max(0, Math.floor(parsed.seq))\n        if (Number.isFinite(parsed.resetEpoch)) resetEpoch = Math.max(0, Math.floor(parsed.resetEpoch))\n        if (Array.isArray(parsed.details)) {\n          for (const r of parsed.details) {\n            if (!isRecord(r)) continue\n            if (!Number.isFinite(r.seq)) needsNumbering = true\n            details.push(r)\n          }\n        }\n        if (parsed.rollups && typeof parsed.rollups === 'object') {\n          for (const dk of Object.keys(parsed.rollups)) {\n            const day = parsed.rollups[dk]\n            if (!day || typeof day !== 'object') continue\n            for (const mk of Object.keys(day)) {\n              const e = day[mk]\n              if (!e || typeof e !== 'object' || typeof e.calls !== 'number') continue\n              rollups[dk] = rollups[dk] || {}\n              rollups[dk][mk] = e\n            }\n          }\n        }\n      }\n      applyRetention(details, rollups, Date.now(), detailDays, resetEpoch)\n      trimDetails()\n      // 旧文件：补配序号（内存生效，下次 persist 落盘）\n      if (needsNumbering) assignSeq()\n      // 兜底：seq 小于现存最大序号时对齐（防止手工编辑过的文件造成重复序号）\n      let maxSeen = 0\n      for (const r of details) if (Number.isFinite(r.seq) && r.seq > maxSeen) maxSeen = r.seq\n      if (maxSeen > seq) seq = maxSeen\n      return details.length\n    } catch (e) {\n      // 损坏时改名备份，从零开始，不阻断启动\n      try { renameSync(filePath, filePath + '.corrupt-' + Date.now()) } catch (e2) {}\n      console.error('cost tracker load failed, starting empty', e)\n      return 0\n    }\n  }\n\n  function isRecord(r) {\n    return !!r && typeof r === 'object' && typeof r.ts === 'number' && r.tokens && typeof r.tokens.input === 'number'\n  }\n\n  function trimDetails() {\n    if (details.length > maxDetails) details.splice(0, details.length - maxDetails)\n  }\n\n  function add(r) {\n    seq += 1\n    r.seq = seq\n    details.push(r)\n    applyRetention(details, rollups, Date.now(), detailDays)\n    trimDetails()\n    return r\n  }\n\n  // 落盘失败只报一次（避免每 1.5 秒刷屏）；恢复后又失败会再次提示\n  let persistWarned = false\n  // 最近一次失败的原因（供调用方在重试链耗尽后打印）\n  let lastPersistError = null\n  let lastPersistTransient = false\n  /** 供调用方在「自己还有重试机会」时静默（quiet=1），等重试链耗尽再报一次 */\n  function persistProblemText(res) {\n    return 'cost tracker persist failed: ' + ((res.error && res.error.message) || String(res.error))\n      + '\\n  原因：' + explainPersistError(res)\n      + '\\n  影响：数据仍在内存中，会在下一次写入时自动重试（不会丢）；'\n      + '若反复出现，请确认没有同时运行两个 dsh 实例'\n  }\n  function persist(opts) {\n    const o = opts || {}\n    const res = writeFileAtomic(filePath, JSON.stringify({ v: 2, seq, resetEpoch, details, rollups }), o)\n    if (res.ok) {\n      lastPersistError = null\n      lastPersistTransient = false\n      if (res.attempts > 1 && !persistWarned) {\n        persistWarned = true\n        console.error('cost tracker persist: 文件被短暂占用，重试 ' + res.attempts + ' 次后已写入（'\n          + explainPersistError({ transient: true }) + '）')\n      } else if (res.attempts === 1) {\n        persistWarned = false\n      }\n      return true\n    }\n    lastPersistError = res.error\n    lastPersistTransient = res.transient === true\n    if (!o.quiet && !persistWarned) {\n      persistWarned = true\n      console.error(persistProblemText(res))\n    }\n    return false\n  }\n  /** 重试链彻底放弃时由调用方打印（保证「只在真的没救时」才出现一次） */\n  function persistProblem() {\n    persistWarned = true\n    return persistProblemText({ error: lastPersistError, transient: lastPersistTransient })\n  }\n\n  function clear() {\n    details.length = 0\n    for (const dk of Object.keys(rollups)) delete rollups[dk]\n    resetEpoch += 1\n    seq = 0\n  }\n\n  function counts() {\n    let calls = details.length\n    for (const dk of Object.keys(rollups)) {\n      for (const mk of Object.keys(rollups[dk])) calls += rollups[dk][mk].calls\n    }\n    return { details: details.length, calls, maxSeq: seq, resetEpoch }\n  }\n\n  return {\n    details, rollups, load, add, persist, persistProblem, clear, counts,\n    /**\n     * 启动时登记实例锁：先把「另一个实例还占着」讲清楚，再写自己的锁。\n     * 只提示、不阻断——多实例本来就是用户的操作问题，不是插件的错误。\n     */\n    lock(opts) {\n      const res = checkStoreLock(filePath, opts)\n      if (res.text) console.error(res.text)\n      writeStoreLock(filePath, opts)\n      return res\n    },\n    releaseLock: () => releaseStoreLock(filePath),\n    /** 当前最大序号（云端水位比较用） */\n    maxSeq: () => seq,\n    /** 清空次数（参与去重键） */\n    epoch: () => resetEpoch,\n    /** 旧文件是否补配过序号（用于首次全量补传判定） */\n    wasRenumbered: () => needsNumbering,\n  }\n}\n"
    },
    {
      "path": "credstore.js",
      "content": "// ============================================================\n// DSH 花费统计插件 —— 凭据库封套 + 出站防护（纯逻辑 + seam 注入，可独立测试）\n//\n// 设计目标：**密钥零落盘**。密钥只存 DSH 凭据库（ctx.credentials，.credentials.yaml\n// 由宿主凭据服务托管），配置文件里只允许出现「是否已配置」的布尔标记。\n//\n// 三层防线：\n//   1. 存取封套：save / resolve / describe / clear —— 统一命名（COST_TRACKER_* 引用名），\n//      未挂载凭据服务时回落「内存态」并在返回值里如实标注（绝不为兼容而悄悄把\n//      明文写回配置文件）；save() 的返回值明确区分「已持久化」与「只在内存里」。\n//   2. 旧明文迁移：migrateLegacySecrets() —— 启动时把 v1.8.x 明文落盘的\n//      volcengineSecretAccessKey（base64 混淆）与 cloudToken 搬进凭据库，\n//      然后从配置对象里清除并回写净化后的配置文件（幂等，带 secretsMigrated 标记）。\n//      **只有确认已持久化才清除明文**：凭据库不可写时保留明文，绝不丢凭据。\n//   3. 出站防护：safeFetch() —— 每一跳都过主机白名单；非 loopback 强制 https；\n//      redirect:'manual' + 自管跳转（最多 3 跳）：**携带凭据的请求不跨主机跟随**\n//      （防重定向把凭据带去别处），不带凭据的请求可在白名单内跟随\n//      （官方定价页 `/pricing` → `/pricing/` 这种同站加斜杠的 302 必须放行）。\n//   4. 响应体自解压（v1.9.4）：**不依赖宿主 fetch 的解压**。宿主进程里只要有任何\n//      插件 `import` 了 npm 的 `undici` 包（本机实测：`dshmarket/lib/net.js` 静态引入，\n//      `dsh-http-proxy` / `dsh-web-fetch-http` 动态引入），Node 内置 `fetch` 就不再\n//      解压 gzip —— 响应既不带 `content-encoding`，body 也是原始压缩字节，于是\n//      `JSON.parse(await res.text())` 必然失败。真实故障：火山方舟配额面板报\n//      「配额响应不是合法 JSON（GetCodingPlanUsage）」，插件市场把所有包的新版本\n//      读成 null（它回退用的也是全局 fetch）。修法有两层：\n//        · 请求默认带 `accept-encoding: identity`，从源头要未压缩正文；\n//        · 收到正文后按**字节**（gzip 1f8b / zlib 78xx / brotli 头）自行解压，\n//          绝不只看响应头 —— 服务端忽略 identity 时同样能正确解析。\n// ============================================================\nimport * as zlib from 'node:zlib'\n\n/** 本插件占用的凭据引用名（POSIX shell 标识符风格，宿主凭据库通用） */\nexport const CRED_REFS = {\n  cloudToken: 'COST_TRACKER_CLOUD_TOKEN',\n  volcengineSecret: 'COST_TRACKER_VOLCENGINE_SK',\n}\n\nfunction isLoopbackHost(host) {\n  return /^(localhost|127\\.0\\.0\\.1|\\[::1?\\]|::1)$/i.test(String(host || ''))\n}\n\n/** gzip 魔数（1f 8b）—— 压缩流的第一、二字节 */\nfunction looksGzip(buf) {\n  return buf.length > 2 && buf[0] === 0x1f && buf[1] === 0x8b\n}\n/** zlib 魔数（78 01 / 78 9c / 78 da）—— 即 `deflate` 头 */\nfunction looksZlib(buf) {\n  return buf.length > 2 && buf[0] === 0x78 && (buf[1] === 0x01 || buf[1] === 0x9c || buf[1] === 0xda)\n}\n\n/**\n * 响应体字节 → 明文 Buffer（v1.9.4）。\n *\n * 判定顺序刻意「先看字节、再看响应头」：宿主全局 fetch 被 undici 包污染后，\n * 响应头里的 `content-encoding` 会消失而正文仍是压缩流，只看头会漏掉；\n * 反过来服务端若已按 `identity` 返回明文，字节判定也不会误伤。\n * 任何解压异常都**原样返回**原始字节 —— 宁可让上层报「不是合法 JSON」，\n * 也不能因为这里的猜测把可读内容弄丢。\n *\n * @param {Buffer} buf - 原始响应体\n * @param {string} contentEncoding - 响应头里声明的编码（可能为空）\n * @returns {Buffer}\n */\nexport function decodeCompressedBody(buf, contentEncoding) {\n  if (!Buffer.isBuffer(buf) || buf.length === 0) return buf\n  const ce = String(contentEncoding || '').trim().toLowerCase()\n  try {\n    if (looksGzip(buf)) return zlib.gunzipSync(buf)\n    if (looksZlib(buf)) return zlib.inflateSync(buf)\n    // brotli / 其它编码没有稳定魔数：只在响应头明说、且确实是压缩流时才尝试\n    if (ce === 'br' || ce === 'brotli') return zlib.brotliDecompressSync(buf)\n    if (ce === 'deflate') return zlib.inflateSync(buf)\n    if (ce === 'gzip' || ce === 'x-gzip') return zlib.gunzipSync(buf)\n  } catch (e) {\n    return buf // 已经解压过 / 截断 / 不是压缩流：交回原样\n  }\n  return buf\n}\n\n/**\n * 把 Response 包成「自带解压」的等价物（v1.9.4）。\n *\n * 只实现调用方真正用到的成员（status / ok / url / redirected / headers /\n * text / json / arrayBuffer），因此对既有接线是透明的；正文只读取一次并缓存，\n * `text()` 与 `json()` 复用同一份解码结果。\n * @param {Response|object} res\n * @returns {object}\n */\nexport function withDecodedBody(res) {\n  let cached = null\n  const bytes = () => {\n    if (cached === null) {\n      cached = (async () => {\n        let raw = Buffer.alloc(0)\n        try {\n          if (typeof res.arrayBuffer === 'function') {\n            raw = Buffer.from(await res.arrayBuffer())\n          } else if (typeof res.text === 'function') {\n            raw = Buffer.from(String(await res.text()), 'utf8')\n          }\n        } catch (e) {\n          raw = Buffer.alloc(0)\n        }\n        const ce = res && res.headers && typeof res.headers.get === 'function' ? res.headers.get('content-encoding') : ''\n        return decodeCompressedBody(raw, ce)\n      })()\n    }\n    return cached\n  }\n  return {\n    status: res.status,\n    ok: res.ok,\n    statusText: res.statusText,\n    url: res.url,\n    redirected: res.redirected,\n    headers: res.headers,\n    text: async () => (await bytes()).toString('utf8'),\n    json: async () => JSON.parse((await bytes()).toString('utf8')),\n    arrayBuffer: async () => {\n      const b = await bytes()\n      return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength)\n    },\n  }\n}\n\n/** 判断请求头里是否已经指定了 accept-encoding（大小写不敏感） */\nfunction hasAcceptEncoding(headers) {\n  return Object.keys(headers || {}).some((k) => k.toLowerCase() === 'accept-encoding')\n}\n\n/** 从 URL 提取 hostname（不含端口）；非法 URL 返回 '' */\nexport function hostnameOf(url) {\n  try {\n    return String(new URL(String(url)).hostname)\n  } catch (e) {\n    return ''\n  }\n}\n\n/**\n * 出站白名单校验。\n * @param {string} url - 目标地址\n * @param {string[]} allowHosts - 允许的 hostname 精确匹配列表（大小写不敏感）\n * @returns {{ok:boolean, reason:string, host:string}}\n */\nexport function assertAllowedHost(url, allowHosts) {\n  const host = hostnameOf(url)\n  if (!host) return { ok: false, reason: 'URL 无法解析', host: '' }\n  const list = (allowHosts || []).map((h) => String(h || '').toLowerCase()).filter(Boolean)\n  const lower = host.toLowerCase()\n  if (list.length && list.indexOf(lower) < 0) {\n    return { ok: false, reason: '目标主机不在出站白名单内：' + lower + '（允许：' + list.join(', ') + '）', host: lower }\n  }\n  const proto = String(new URL(String(url)).protocol || '').toLowerCase()\n  if (proto !== 'https:' && !isLoopbackHost(host)) {\n    return { ok: false, reason: '非本机地址必须使用 https（当前 ' + proto + '）', host: lower }\n  }\n  return { ok: true, reason: '', host: lower }\n}\n\n/**\n * 带防护的 fetch 封套（v1.9.0，含重定向策略）。\n *\n * ⚠️ **必须同时接受两种入参形状**（v1.9.0 首个版本的缺陷教训）：\n *   · `safeFetch(url, { init: { method, body }, allowHosts })` —— 本模块自己的文档形状；\n *   · `safeFetch(url, { method, body, headers, allowHosts })` —— **fetch 原生签名**，\n *     即 `<typeof fetch>` 位置上的封装写法 `(url, init) => safeFetch(url, { ...init, allowHosts })`。\n * 只认 `opts.init` 会让后者丢掉 method/body：POST 静默退化成 GET、请求体消失，\n * 云端回 405「方法不允许」——真实故障现场就是同步全面失败、水位不前进。\n * 因此 fetch 的 init 字段在顶层也识别一遍（`opts.init` 优先）。\n *\n * 规则（按「凭据是否会跟着跑」区分，而不是一刀切拒绝 3xx）：\n *   · 每次请求（含每一跳）都过 `assertAllowedHost`：主机白名单 + 非本机强制 https；\n *   · `redirect: 'manual'` 自己处理跳转，最多 3 跳；\n *   · **携带凭据**（authorization / api-key 等头）的请求**不跨主机跟随** ——\n *     跨主机重定向一律失败并点名去向主机，这就是「防凭据外带」的硬边界；\n *   · 不带凭据的请求（如抓取官方定价页：`/pricing` → `/pricing/` 这种同站加斜杠）\n *     可以在白名单内跟随，否则会把正常功能也一并挡死。\n *\n * @param {string} url\n * @param {{headers?:object, init?:object, allowHosts?:string[], timeoutMs?:number, fetchFn?:typeof fetch}} opts\n */\nexport async function safeFetch(url, opts) {\n  const o = opts || {}\n  const f = o.fetchFn || globalThis.fetch\n  const allowHosts = o.allowHosts || []\n  const MAX_HOPS = 3\n  const init = Object.assign({}, o.init || {})\n  // ⚠️ 顶层 fetch 同名字段兜底（`opts.init` 优先）。v1.9.0 首个版本的缺陷就在\n  // 这里：index.js 按 fetch 原生签名接线 `(url, init) => safeFetch(url, {...init, allowHosts})`，\n  // 而本函数当时只读 `opts.init`，于是 method/body 被丢掉 —— POST 静默退化成 GET、\n  // 请求体消失，云端回 405「方法不允许」，同步全面失败（水位不前进）。\n  for (const k of ['method', 'body', 'headers', 'signal', 'cache', 'credentials', 'mode', 'referrer', 'referrerPolicy', 'integrity', 'keepalive', 'window', 'duplex']) {\n    if (o[k] !== undefined && init[k] === undefined) init[k] = o[k]\n  }\n  // init.headers 在前、opts.headers 在后：调用方经 init 传的签名头不被覆盖\n  const headers = Object.assign({}, init.headers || {}, o.headers || {})\n  // v1.9.4：从源头要未压缩正文（宿主全局 fetch 可能已不解压，见文件头「响应体自解压」）。\n  // 调用方显式指定过 accept-encoding 时尊重调用方。\n  if (!hasAcceptEncoding(headers)) headers['accept-encoding'] = 'identity'\n  const credentialHeader = Object.keys(headers).find((k) => /^(authorization|proxy-authorization|x-api-key|api-key)$/i.test(k))\n  let current = String(url)\n  let method = init.method\n  let body = init.body\n\n  for (let hop = 0; hop <= MAX_HOPS; hop += 1) {\n    const guard = assertAllowedHost(current, allowHosts)\n    if (!guard.ok) throw new Error('出站被拒绝：' + guard.reason)\n    const ac = new AbortController()\n    const timer = setTimeout(() => ac.abort(), o.timeoutMs || 15000)\n    let res\n    try {\n      res = await f(current, Object.assign({}, init, { method, body, headers, redirect: 'manual', signal: ac.signal }))\n    } finally {\n      clearTimeout(timer)\n    }\n    if (!(res.status >= 300 && res.status < 400)) return withDecodedBody(res)\n    const loc = typeof res.headers.get === 'function' ? (res.headers.get('location') || '') : ''\n    if (!loc) return withDecodedBody(res) // 3xx 但没给 Location：交给调用方按状态自行判断\n    let target\n    try {\n      target = new URL(loc, current).toString()\n    } catch (e) {\n      throw new Error('重定向目标无法解析：' + loc)\n    }\n    const fromHost = hostnameOf(current)\n    const toHost = hostnameOf(target)\n    if (credentialHeader && toHost !== fromHost) {\n      throw new Error('目标返回跨主机重定向 ' + res.status + ' → ' + toHost + '（携带 ' + credentialHeader + ' 的请求不跨主机跟随，防止凭据外带）')\n    }\n    const hopGuard = assertAllowedHost(target, allowHosts)\n    if (!hopGuard.ok) throw new Error('重定向被拒绝（' + res.status + ' → ' + toHost + '）：' + hopGuard.reason)\n    if (hop === MAX_HOPS) throw new Error('重定向次数过多（>' + MAX_HOPS + ' 跳），已放弃：' + target)\n    // 303（以及 301/302 上的 POST）按 HTTP 语义降级为 GET 并丢弃 body\n    if (res.status === 303 || ((res.status === 301 || res.status === 302) && String(method || '').toUpperCase() === 'POST')) {\n      method = 'GET'\n      body = undefined\n    }\n    current = target\n  }\n  throw new Error('重定向处理异常')\n}\n\n/**\n * 凭据封套工厂：包装宿主 credentials 服务；未挂载或只读时退化为**内存态**存储，\n * 并通过 backend 如实标注（'memory' / 'credentials'），调用方据此在 UI 提示\n * 「凭据库不可用，密钥仅保存在本进程内存，重启后需重填」。\n *\n * `save()` 的返回值语义（v1.9.0 起明确）：\n *   true  = **已持久化**到凭据库（重启后仍在）；\n *   false = 只写进了进程内存（凭据服务缺席或只读）—— 迁移逻辑据此决定\n *           「能不能把配置文件里的明文删掉」，避免为了「零明文」而丢凭据。\n *\n * @param {object|undefined} cred - ctx.get('credentials')（可能为 undefined）\n * @returns {{backend:string, durable:boolean, save:async, resolve:async, describe:async, clear:async}}\n */\nexport function createCredSeam(cred) {\n  const memory = new Map()\n  const usable = !!cred && typeof cred.resolve === 'function'\n  const durable = usable && typeof cred.set === 'function' && typeof cred.unset === 'function'\n  return {\n    backend: durable ? 'credentials' : 'memory',\n    durable,\n    async save(ref, value) {\n      const v = String(value == null ? '' : value).trim()\n      if (!v) return false\n      if (durable) {\n        await cred.set(ref, v)\n        return true\n      }\n      // 只读/无凭据服务：留一份内存副本让本次进程可用，但**不算持久化**\n      memory.set(ref, v)\n      return false\n    },\n    async resolve(ref) {\n      if (usable) {\n        try {\n          const r = await cred.resolve(ref)\n          if (r && r.value) return { value: String(r.value), backend: 'credentials' }\n        } catch (e) { /* 落到内存态 */ }\n      }\n      if (memory.has(ref)) return { value: memory.get(ref), backend: 'memory' }\n      return { value: '', backend: usable ? 'credentials' : 'memory' }\n    },\n    async describe(ref) {\n      if (usable && typeof cred.describe === 'function') {\n        try {\n          const d = await cred.describe(ref)\n          if (d && (d.configured || d.configured === 'local-store')) return { configured: true, writable: d.writable !== false, backend: 'credentials' }\n        } catch (e) { /* 落内存态 */ }\n      }\n      return { configured: memory.has(ref), writable: durable, backend: durable ? 'credentials' : 'memory' }\n    },\n    async clear(ref) {\n      memory.delete(ref)\n      if (durable) {\n        try { await cred.unset(ref) } catch (e) { /* 尽力而为 */ }\n      }\n      return true\n    },\n  }\n}\n\n/**\n * v1.8.x 明文密钥迁移（幂等）。\n *\n * 旧版把 volcengineSecretAccessKey（base64 混淆后）与 cloudToken 直接写进\n * cost-tracker-config.json。本函数把它们搬进凭据库，然后**清除配置对象里的\n * 明文字段**并返回 {changed}；调用方负责把净化后的配置落盘。\n *\n * **安全边界**：只有当凭据库确实可写（`save()` 返回 true，即已持久化）时才清除\n * 配置里的明文。宿主没有凭据服务、或凭据服务只读时，明文**原样保留** ——\n * 「配置文件零明文」不能以丢凭据为代价（那种情况下密钥只在内存里，重启即失效）。\n *\n * 迁移后 SK/AK 查询链：凭据库 → 环境变量（原有链保持不变）。\n *\n * @param {object} cfg - normalizePluginConfig 产出的配置对象（会被就地修改）\n * @param {object} seam - createCredSeam 的实例\n * @returns {Promise<{changed:boolean, moved:string[], notes:string[]}>}\n */\nexport async function migrateLegacySecrets(cfg, seam) {\n  const moved = []\n  const notes = []\n  let pending = false\n  if (!cfg || typeof cfg !== 'object') return { changed: false, moved, notes, pending }\n  /** 逐项搬运：只有持久化成功才清空配置字段 */\n  async function move(field, ref, label) {\n    const value = String(cfg[field] || '').trim()\n    if (!value) return\n    const d = await seam.describe(ref)\n    if (d.configured) {\n      // 凭据库已有值 → 不覆盖（旧文件里的可能是陈值），但仍清掉配置里的明文\n      cfg[field] = ''\n      notes.push('凭据库中已有 ' + ref + '，配置文件里的旧值直接丢弃（不覆盖凭据库）')\n      return\n    }\n    const persisted = await seam.save(ref, value)\n    if (persisted) {\n      cfg[field] = ''\n      moved.push(label + ' → ' + ref)\n    } else {\n      // 无法持久化：保留明文，避免「文件干净了、密钥却没了」\n      pending = true\n      notes.push('凭据库不可写（宿主未提供凭据服务？）：' + label + ' 的明文**保留在配置文件**中以免丢失，'\n        + '请修复凭据库后重启以完成迁移')\n    }\n  }\n  await move('volcengineSecretAccessKey', CRED_REFS.volcengineSecret, 'volcengineSecretAccessKey')\n  await move('cloudToken', CRED_REFS.cloudToken, 'cloudToken')\n  return { changed: moved.length > 0, moved, notes, pending }\n}\n"
    }
